mapper.update:
UPDATE memory_note
confidence = #{confidence}, status = #{status}, evidence_count = #{evidenceCount}, valid_to = #{validTo}, updated_at = #{updatedAt}
WHERE id = CAST(#{id} AS uuid)

mapper.select:
SELECT *, structured_content::text AS structured_content
FROM memory_note
WHERE tenant_id = #{tenantId}
  AND owner_id = #{ownerId}
  AND scope = #{scope}
  AND subject = #{subject}
  AND status = 'ACTIVE'
  AND (agent_id = CAST(#{agentId} AS uuid) OR (agent_id IS NULL AND #{agentId} IS NULL))
ORDER BY version DESC
LIMIT 1

SELECT *, structured_content::text AS structured_content
FROM memory_note
WHERE tenant_id = #{tenantId}
  AND owner_id = #{ownerId}
  AND status = 'ACTIVE'
  AND (agent_id = CAST(#{agentId} AS uuid) OR agent_id IS NULL)
ORDER BY salience DESC, confidence DESC, updated_at DESC
LIMIT #{limit}
